import React, { useEffect, useState } from 'react';
import axios from 'axios';
import { useAuth } from '../context/AuthContext';
import Navbar from '../components/Navbar';
import Footer from '../components/Footer';
import KibaShield from '../components/KibaShield';

const API = process.env.REACT_APP_API_URL || 'http://localhost:5000';

const skillOptions = [
  'Customer Service', 'Data Entry', 'Driving', 'Security',
  'Cleaning and Hygiene', 'Cooking and Catering', 'Construction',
  'Plumbing', 'Electrical Work', 'Retail and Sales', 'Teaching',
  'Healthcare Support', 'IT Support', 'Accounting', 'Administration'
];

const TalentPool = () => {
  const { token, darkMode } = useAuth();
  const [talent, setTalent] = useState(null);
  const [loading, setLoading] = useState(true);
  const [joining, setJoining] = useState(false);
  const [withdrawing, setWithdrawing] = useState(false);
  const [selectedSkills, setSelectedSkills] = useState([]);
  const [pose, setPose] = useState(1);
  const [shieldState, setShieldState] = useState('idle');
  const [message, setMessage] = useState('');
  const [error, setError] = useState('');

  useEffect(() => {
    fetchTalent();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchTalent = async () => {
    try {
      const res = await axios.get(`${API}/api/talent/my`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setTalent(res.data);
      if (res.data?.status === 'active') {
        setPose(8);
        setShieldState('idle');
      }
    } catch (err) {
      console.error('Error fetching talent pool:', err);
    } finally {
      setLoading(false);
    }
  };

  const toggleSkill = (skill) => {
    setSelectedSkills(prev =>
      prev.includes(skill) ? prev.filter(s => s !== skill) : [...prev, skill]
    );
  };

  const handleJoin = async () => {
    if (selectedSkills.length === 0) {
      setError('Please select at least one skill category');
      setPose(3);
      setShieldState('warning');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
      return;
    }
    setJoining(true);
    setPose(7);
    setError('');
    try {
      await axios.post(`${API}/api/talent/join`,
        { skillCategories: selectedSkills },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setMessage('You have joined the talent pool successfully. We will notify you when matching jobs are posted.');
      setPose(2);
      setShieldState('success');
      fetchTalent();
      setTimeout(() => { setPose(8); setShieldState('idle'); }, 3000);
    } catch (err) {
      setError(err.response?.data?.message || 'Something went wrong. Please try again.');
      setPose(4);
      setShieldState('danger');
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 2000);
    } finally {
      setJoining(false);
    }
  };

  const handleWithdraw = async () => {
    if (!window.confirm('Are you sure you want to leave the talent pool? You can rejoin at any time.')) return;
    setWithdrawing(true);
    setPose(7);
    try {
      await axios.put(`${API}/api/talent/withdraw`, {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setMessage('You have been removed from the talent pool.');
      setPose(5);
      setShieldState('blue');
      fetchTalent();
      setTimeout(() => { setPose(1); setShieldState('idle'); }, 3000);
    } catch (err) {
      setError('Something went wrong. Please try again.');
    } finally {
      setWithdrawing(false);
    }
  };

  const card = { background: darkMode ? '#1E293B' : '#fff', borderRadius: '16px', padding: '28px', boxShadow: '0 4px 24px rgba(30,58,95,0.08)', marginBottom: '20px' };

  return (
    <div style={{ minHeight: '100vh', display: 'flex', flexDirection: 'column', background: darkMode ? '#0F172A' : '#F8FAFC' }}>
      <Navbar />
      <div style={{ flex: 1, padding: '32px 24px', maxWidth: '960px', margin: '0 auto', width: '100%' }}>
        <h1 style={{ fontSize: '28px', fontWeight: 800, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '4px' }}>Talent Pool</h1>
        <p style={{ color: '#64748B', fontSize: '14px', marginBottom: '32px' }}>Join the talent pool and get notified when jobs matching your skills are posted</p>

        <div style={{ display: 'flex', gap: '40px', alignItems: 'flex-start', flexWrap: 'wrap' }}>
          <div style={{ display: 'flex', flexDirection: 'column', alignItems: 'center' }}>
            <KibaShield pose={pose} shieldState={shieldState} />
          </div>

          <div style={{ flex: 1, minWidth: '280px' }}>
            {message && <div style={{ background: '#F0FDF4', color: '#10B981', border: '1px solid #BBF7D0', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', marginBottom: '20px' }}>{message}</div>}
            {error && <div style={{ background: '#FEF2F2', color: '#EF4444', border: '1px solid #FECACA', borderRadius: '12px', padding: '13px 16px', fontSize: '14px', marginBottom: '20px' }}>{error}</div>}

            {loading ? (
              <p style={{ color: '#64748B' }}>Loading talent pool status...</p>
            ) : talent?.status === 'active' ? (
              <div style={card}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '12px', marginBottom: '20px' }}>
                  <div>
                    <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '4px' }}>You are in the talent pool</h3>
                    <p style={{ fontSize: '13px', color: '#64748B' }}>Consent expires: {new Date(talent.consentExpiry).toLocaleDateString()}</p>
                  </div>
                  <span style={{ padding: '4px 14px', borderRadius: '999px', background: '#D1FAE5', color: '#065F46', fontSize: '12px', fontWeight: 700 }}>ACTIVE</span>
                </div>

                <div style={{ marginBottom: '20px' }}>
                  <p style={{ fontSize: '13px', fontWeight: 600, color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '10px' }}>Your skill categories:</p>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                    {talent.skillCategories?.map(skill => (
                      <span key={skill} style={{ padding: '6px 14px', background: '#E0F2FE', color: '#075985', borderRadius: '999px', fontSize: '13px', fontWeight: 600 }}>{skill}</span>
                    ))}
                  </div>
                </div>

                <div style={{ background: '#F0FDF4', borderRadius: '12px', padding: '14px 16px', marginBottom: '20px' }}>
                  <p style={{ fontSize: '13px', color: '#065F46', lineHeight: 1.6 }}>
                    You will receive a notification from Kiba whenever a new job matching your skills is posted. Your consent to be in the talent pool expires automatically in 6 months.
                  </p>
                </div>

                <button onClick={handleWithdraw} disabled={withdrawing}
                  style={{ width: '100%', padding: '13px', background: '#EF4444', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 700, fontSize: '14px', cursor: withdrawing ? 'not-allowed' : 'pointer', fontFamily: 'Inter, sans-serif', opacity: withdrawing ? 0.7 : 1 }}>
                  {withdrawing ? 'Leaving talent pool...' : 'Leave Talent Pool'}
                </button>
              </div>
            ) : (
              <div style={card}>
                <h3 style={{ fontSize: '16px', fontWeight: 700, color: darkMode ? '#F1F5F9' : '#1E3A5F', marginBottom: '6px' }}>Join the talent pool</h3>
                <p style={{ fontSize: '13px', color: '#64748B', marginBottom: '20px' }}>Select your skill categories. We will notify you when matching jobs are posted. Your consent lasts 6 months and you can withdraw at any time.</p>

                <div style={{ marginBottom: '24px' }}>
                  <p style={{ fontSize: '13px', fontWeight: 600, color: darkMode ? '#CBD5E1' : '#1E293B', marginBottom: '12px' }}>Select your skills:</p>
                  <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px' }}>
                    {skillOptions.map(skill => (
                      <button key={skill} type="button" onClick={() => toggleSkill(skill)}
                        style={{ padding: '8px 14px', borderRadius: '999px', border: '2px solid', borderColor: selectedSkills.includes(skill) ? '#0EA5E9' : '#E2E8F0', background: selectedSkills.includes(skill) ? '#E0F2FE' : 'transparent', color: selectedSkills.includes(skill) ? '#075985' : '#64748B', fontSize: '13px', fontWeight: 600, cursor: 'pointer', fontFamily: 'Inter, sans-serif', transition: 'all 0.2s' }}>
                        {selectedSkills.includes(skill) ? '✓ ' : ''}{skill}
                      </button>
                    ))}
                  </div>
                </div>

                <div style={{ background: '#EFF6FF', borderRadius: '12px', padding: '14px 16px', marginBottom: '20px' }}>
                  <p style={{ fontSize: '13px', color: '#1D4ED8', lineHeight: 1.6 }}>
                    By joining the talent pool you give KibaliGuard consent to match your profile with open positions for 6 months. You can withdraw this consent at any time and your data will no longer be used for matching.
                  </p>
                </div>

                <button onClick={handleJoin} disabled={joining}
                  style={{ width: '100%', padding: '14px', background: joining ? '#0EA5E9' : '#1E3A5F', color: '#fff', border: 'none', borderRadius: '12px', fontWeight: 700, fontSize: '15px', cursor: joining ? 'not-allowed' : 'pointer', fontFamily: 'Inter, sans-serif', display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px' }}>
                  {joining ? (
                    <>
                      <span style={{ width: '16px', height: '16px', border: '2px solid rgba(255,255,255,0.3)', borderTop: '2px solid #fff', borderRadius: '50%', display: 'inline-block', animation: 'kibashield-spin 0.8s linear infinite' }} />
                      Joining talent pool...
                    </>
                  ) : 'Join Talent Pool'}
                </button>
              </div>
            )}
          </div>
        </div>
      </div>
      <Footer />
    </div>
  );
};

export default TalentPool;
